    // It is assumed that IsomorphicGraphMapping has a constructor that
    // accepts source and target graphs and that mapping vertices to themselves
    // is handled internally when source and target are the same instance.
    return new IsomorphicGraphMapping<>(graph, graph);
}

public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph){
