}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }
    if (!file.exists()) {
        return; // nothing to do
    }
    if (file.isDirectory()) {
        deleteDirectoryOnExitRecursive(file);
    } else {
        if (!file.deleteOnExit()) {
            throw new IOException("Unable to schedule deletion for file: " + file);
        }
    }
}

/* recursively schedules deletion of all files within the given directory and the directory itself */
private static void deleteDirectoryOnExitRecursive(File dir) throws IOException {
    File[] files = dir.listFiles();
    if (files != null) {
        for (File f : files) {
            if (f.isDirectory()) {
                deleteDirectoryOnExitRecursive(f);
            } else {
                if (!f.deleteOnExit()) {
                    throw new IOException("Unable to schedule deletion for file: " + f);
                }
            }
        }
    }
    if (!dir.deleteOnExit()) {
        throw new IOException("Unable to schedule deletion for directory: " + dir);
    }
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file");
    }
    if (!file.exists()) {
        return;
    }
    if (file.isDirectory()) {
        File[] children = file.listFiles();
        if (children != null) {
            for (File child : children) {
                forceDeleteOnExit(child);
            }
        }
    }
    try {
        file.deleteOnExit();
    } catch (SecurityException e) {
        throw new IOException("Failed to schedule deletion for " + file, e);
    }
}

public static void forceDeleteOnExit(java.io.File file) throws java.io.IOException {
    if (file == null) throw new java.lang.NullPointerException("file");
    if (file.isDirectory()) {
        final java.util.List<java.io.File> filesToDelete = new java.util.ArrayList<>();
        java.util.Deque<java.io.File> stack = new java.util.ArrayDeque<>();
        stack.push(file);
        while (!stack.isEmpty()) {
            java.io.File current = stack.pop();
            if (current.isDirectory()) {
                java.io.File[] children = current.listFiles();
                if (children != null) {
                    for (java.io.File child : children) {
                        stack.push(child);
                    }
                }
            }
            filesToDelete.add(current);
        }
        java.lang.Runtime.getRuntime().addShutdownHook(new java.lang.Thread(() -> {
            java.util.Collections.reverse(filesToDelete);
            for (java.io.File f : filesToDelete) {
                f.delete();
            }
        }));
    } else {
        file.deleteOnExit();
    }
}

