@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Target graph and resultMap cannot be null");
    }
    // Collect all vertices from the resultMap
    List<V> vertices = new ArrayList<>(resultMap.values());
    int n = vertices.size();
    if (n < 2) {
        // A bipartite graph with fewer than two vertices is trivial
        return;
    }
    // Divide the vertices roughly into two partitions
    int leftSize = n / 2;
    List<V> left = vertices.subList(0, leftSize);
    List<V> right = vertices.subList(leftSize, n);
    // Ensure that the target graph contains these vertices
    for (V v : vertices) {
        if (!target.containsVertex(v)) {
            target.addVertex(v);
        }
    }
    // Add edges between every pair of vertices from different partitions
    for (V u : left) {
        for (V v : right) {
            // Only add if the edge does not already exist
            if (target.getEdge(u, v) == null) {
                target.addEdge(u, v);
            }
        }
    }
}

@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    // Create two vertices (representing two partitions of the bipartite graph)
    V left = (V)(Object)0;
    V right = (V)(Object)1;
    // Add vertices to the target graph
    target.addVertex(left);
    target.addVertex(right);
    // Connect every vertex from the left partition to every vertex from the right partition
    target.addEdge(left, right);
    // Record the newly created vertices in the result map
    resultMap.put("left", left);
    resultMap.put("right", right);
}

@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    try{
        List<V> vertices = new ArrayList<>(resultMap.values());
        // add all vertices to the graph
        for(V v : vertices){
            target.addVertex(v);
        }
        // split into two partitions: first half and second half
        int mid = vertices.size() / 2;
        for(int i = 0; i < mid; i++){
            for(int j = mid; j < vertices.size(); j++){
                target.addEdge(vertices.get(i), vertices.get(j));
            }
        }
    }catch(Exception e){
        throw new RuntimeException("Failed to generate complete bipartite graph", e);
    }
}

@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    // Assume the resultMap contains vertices belonging to two parts, 
    // identified by a key prefix "L" (left) and "R" (right).
    List<V> left = new ArrayList<>();
    List<V> right = new ArrayList<>();
    for (Map.Entry<String,V> entry : resultMap.entrySet()){
        String key = entry.getKey();
        if (key.startsWith("L")) {
            left.add(entry.getValue());
        } else if (key.startsWith("R")) {
            right.add(entry.getValue());
        }
    }
    // Add all vertices to the target graph if they are not yet present
    for (V v : resultMap.values()){
        if (!target.containsVertex(v)) {
            target.addVertex(v);
        }
    }
    // Add edges to form a complete bipartite graph between the two parts.
    for (V u : left){
        for (V v : right){
            // Check for existing edge to avoid duplicates
            if (target.getEdge(u, v) == null) {
                target.addEdge(u, v);
            }
        }
    }
}

