    if (buffer == null) return -1;
    int len = buffer.length;
    if (pos < 0) pos = 0;
    if (pos >= len) return -1;
    for (int i = pos; i < len; i++) {
        if (buffer[i] == value) return i;
    }
    return -1;
}

