protected int findByte(byte value, int pos) {
    // Safety check: if buffer is null or length is zero, nothing to find.
    if (buffer == null || len == 0) {
        return -1;
    }

    // Clamp the starting position to a valid range.
    if (pos < 0) {
        pos = 0;
    } else if (pos >= len) {
        return -1;
    }

    // Scan the buffer from the starting position to the end.
    for (int i = pos; i < len; i++) {
        if (buffer[i] == value) {
            return i;
        }
    }

    // If the value was not found, return -1.
    return -1;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("OutputStream is null");
    }
    if (message == null) {
        throw new IllegalArgumentException("Message is null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema is null");
    }

    int size = schema.getSerializedSize(message);

    // Write the length prefix as a varint
    int temp = size;
    while ((temp & ~0x7F) != 0) {
        out.write((temp & 0x7F) | 0x80);
        temp >>>= 7;
    }
    out.write(temp);

    // Serialize the message
    byte[] buf = new byte[size];
    schema.writeTo(message, buf, 0, buf.length);
    out.write(buf);
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new NullPointerException("OutputStream is null");
    }
    if (message == null) {
        throw new NullPointerException("Message is null");
    }
    if (schema == null) {
        throw new NullPointerException("Schema is null");
    }
    if (buffer == null) {
        throw new NullPointerException("Buffer is null");
    }
    // Calculate the serialized size of the message
    int size = schema.getSerializedSize(message);
    // Create a coded output stream backed by the given OutputStream
    CodedOutputStream cosForHeader = CodedOutputStream.newInstance(out);
    // Write the length prefix as a varint32
    cosForHeader.writeRawVarint32(size);
    // Reset the buffer to reuse it for the message serialization
    buffer.reset();
    // Create a coded output stream for the buffer
    CodedOutputStream cosForBuffer = CodedOutputStream.newInstance(buffer);
    // Write the message to the buffer
    schema.write(message, cosForBuffer);
    cosForBuffer.flush();
    // Now write the contents of the buffer to the underlying output stream
    buffer.writeTo(cosForHeader);
    cosForHeader.flush();
    return size;
}

public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    // Encode the message into the buffer
    schema.encode(message, buffer);
    // Get the length of the encoded data
    int size = buffer.getLength();
    // Write the length in varint32 format
    int temp = size;
    while ((temp & 0xFFFFFF80) != 0) {
        out.write((temp & 0x7F) | 0x80);
        temp >>>= 7;
    }
    out.write(temp);
    // Write the raw bytes of the message
    byte[] bytes = buffer.toByteArray();
    out.write(bytes, 0, size);
    // Clear buffer for reuse
    buffer.clear();
    return size;
}

