            ParameterizedType superPT = (ParameterizedType) superType;
            Class<?> superRaw = (Class<?>) superPT.getRawType();
            if (superRaw.equals(raw)) {
                TypeVariable<?>[] vars = raw.getTypeParameters();
                Type[] actuals = superPT.getActualTypeArguments();
                for (int i = 0; i < vars.length; i++) {
                    typeVarMap.put(vars[i], actuals[i]);
                }
                break;
            }
        }
        current = current.getSuperclass();
    }

    // helper to resolve a Type to Class<?> using the map
    java.util.function.Function<Type, Class<?>> resolveToClass = new java.util.function.Function<Type, Class<?>>() {
        @Override
        public Class<?> apply(Type t) {
            if (t instanceof Class) {
                return (Class<?>) t;
            }
            if (t instanceof ParameterizedType) {
                Type rt = ((ParameterizedType) t).getRawType();
                return rt instanceof Class ? (Class<?>) rt : null;
            }
            if (t instanceof TypeVariable) {
                Type v = typeVarMap.get(t);
                if (v == null) {
