private static Class<?> resolveToClass(Type type, Class<?> context) {
    if (type instanceof Class) {
        return (Class<?>) type;
    }
    if (type instanceof ParameterizedType) {
        return (Class<?>) ((ParameterizedType) type).getRawType();
    }
    if (type instanceof GenericArrayType) {
        GenericArrayType gat = (GenericArrayType) type;
        Class<?> component = resolveToClass(gat.getGenericComponentType(), context);
        return java.lang.reflect.Array.newInstance(component, 0).getClass();
    }
    if (type instanceof TypeVariable) {
        TypeVariable<?> tv = (TypeVariable<?>) type;
        Type resolved = resolveTypeVariable(context, tv);
        if (resolved != null) {
            return resolveToClass(resolved, context);
        }
        return Object.class;
    }
    if (type instanceof WildcardType) {
        return Object.class;
    }
    return Object.class;
}

private static Type resolveTypeVariable(Class<?> context, TypeVariable<?> variable) {
    // Traverse the class hierarchy to find a concrete type for the variable
    while (context != null) {
        Type genericSuper = context.getGenericSuperclass();
        if (genericSuper != null) {
            Type resolved = matchVariable(genericSuper, variable);
            if (resolved != null) {
                return resolved;
            }
        }
        for (Type iface : context.getGenericInterfaces()) {
            Type resolved = matchVariable(iface, variable);
            if (resolved != null) {
                return resolved;
            }
        }
        context = context.getSuperclass();
    }
    return null;
}

private static Type matchVariable(Type type, TypeVariable<?> variable) {
    if (type instanceof ParameterizedType) {
        ParameterizedType pt = (ParameterizedType) type;
        Class<?> raw = (Class<?>) pt.getRawType();
        TypeVariable<?>[] vars = raw.getTypeParameters();
        for (int i = 0; i < vars.length; i++) {
            if (vars[i].getName().equals(variable.getName())) {
                return pt.getActualTypeArguments()[i];
            }
        }
    }
    return null;
}

