public static void createConfigurationDirectory(){
    String osName = System.getProperty("os.name");
    String userHome = System.getProperty("user.home");
    if (userHome == null) {
        throw new RuntimeException("System property user.home is not set");
    }
    String basePath;
    if (osName != null && osName.contains("Windows 2000")) {
        // On Windows 2000, user.home points to a subdirectory of "Documents and Settings".
        // Take the parent directory to get "Documents and Settings".
        basePath = new File(userHome).getParent();
        if (basePath == null) {
            // Fallback if parent is unexpectedly null
            basePath = System.getProperty("user.dir");
        }
    } else {
        basePath = userHome;
    }
    File configDir = new File(basePath, "lf5");
    if (!configDir.exists()) {
        boolean created = configDir.mkdirs();
        if (!created && !configDir.exists()) {
            throw new RuntimeException("Could not create configuration directory: " + configDir.getAbsolutePath());
        }
    }
}

public long readLong(final int offset){
    try {
        return ((long)readInt(offset)) << 32 | 0xffffffffL & readInt(offset + 4);
    } catch (Exception e) {
        throw new RuntimeException(e);
    }
}

