public long readLong(final int offset){
    // Ensure the offset is valid for reading an 8-byte signed long
    if (offset < 0 || offset + 8 > this.buf.length) {
        throw new IllegalArgumentException("offset out of bounds");
    }
    // Build the long value from the buffer, treating bytes as unsigned?
    return ((long) (this.buf[offset]   & 0xFF) << 56)
        | ((long) (this.buf[offset+1] & 0xFF) << 48)
        | ((long) (this.buf[offset+2] & 0xFF) << 40)
        | ((long) (this.buf[offset+3] & 0xFF) << 32)
        | ((long) (this.buf[offset+4] & 0xFF) << 24)
        | ((long) (this.buf[offset+5] & 0xFF) << 16)
        | ((long) (this.buf[offset+6] & 0xFF) << 8)
        | ((long) (this.buf[offset+7] & 0xFF));
}

public long readLong(final int offset){
    final byte[] data = this.bytes;
    if (offset < 0 || offset + 8 > data.length) {
        throw new ArrayIndexOutOfBoundsException();
    }
    return ((long)(data[offset] & 0xFF) << 56)
           | ((long)(data[offset + 1] & 0xFF) << 48)
           | ((long)(data[offset + 2] & 0xFF) << 40)
           | ((long)(data[offset + 3] & 0xFF) << 32)
           | ((long)(data[offset + 4] & 0xFF) << 24)
           | ((long)(data[offset + 5] & 0xFF) << 16)
           | ((long)(data[offset + 6] & 0xFF) << 8)
           | ((long)(data[offset + 7] & 0xFF));
}

public boolean equals(final byte[] data,int offset,final int len){
    if (data == null) {
        return false;
    }
    if (offset < 0 || len < 0 || offset + len > data.length) {
        return false;
    }
    // Assume the internal array reference is named 'array' in this class
    byte[] array = this.array; // using this.array directly; if field name differs adjust accordingly
    if (array == null) {
        return false;
    }
    if (len != array.length) {
        return false;
    }
    for (int i = 0; i < len; i++) {
        if (array[i] != data[offset + i]) {
            return false;
        }
    }
    return true;
}

public boolean equals(final byte[] data, int offset, final int len) {
    // Validate parameters
    if (data == null || len < 0 || offset < 0 || offset + len > data.length) {
        return false;
    }

    // If internal array is null, only equal if len is 0 and data slice is also empty
    if (this.array == null) {
        return len == 0;
    }

    // Length mismatch
    if (this.array.length != len) {
        return false;
    }

    // Element-wise comparison
    for (int i = 0; i < len; i++) {
        if (this.array[i] != data[offset + i]) {
            return false;
        }
    }

    return true;
}

