protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    // Ensure a valid range: if start is after end, swap them
    if (start > end) {
        long tmp = start;
        start = end;
        end = tmp;
    }
    if (start == end) {
        // No range to split
        return ranges;
    }
    // Split the interval into smaller segments of at most FETCH_DATA_DURATION
    long step = FETCH_DATA_DURATION;
    long current = start;
    while (current < end) {
        // Avoid overflow when adding step
        long next = Math.min(current + step, end);
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    // Validate input
    if (start >= end) {
        return ranges;
    }
    // Avoid division by zero or negative durations
    long maxDuration = FETCH_DATA_DURATION;
    if (maxDuration <= 0) {
        ranges.add(new TimeRange(start, end));
        return ranges;
    }
    long currentStart = start;
    long remaining = end - currentStart;
    while (remaining > maxDuration) {
        long rangeEnd = currentStart + maxDuration;
        ranges.add(new TimeRange(currentStart, rangeEnd));
        currentStart = rangeEnd;
        remaining = end - currentStart;
    }
    // Add the final (possibly smaller) range
    if (currentStart < end) {
        ranges.add(new TimeRange(currentStart, end));
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start,long end){
    List<TimeRange> ranges = new ArrayList<TimeRange>();
    if(start >= end){
        return ranges;
    }
    while(start < end){
        long segmentEnd = start + FETCH_DATA_DURATION;
        if(segmentEnd < start || segmentEnd > end){
            segmentEnd = end;
        }
        ranges.add(new TimeRange(start, segmentEnd));
        start = segmentEnd;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start,long end){
    if(start<0 || end<start){
        throw new IllegalArgumentException("Start time must be non-negative and less than or equal to end time");
    }
    List<TimeRange> ranges = new ArrayList<>();
    long current = start;
    while(current < end){
        long next = Math.min(current + FETCH_DATA_DURATION, end);
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

