static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0){
        throw new IllegalArgumentException("dayStep must be positive");
    }
    long year = timeBucket / 10000;
    long month = (timeBucket / 100) % 100;
    long day = timeBucket % 100;
    // compute the start day of the interval
    long newDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000 + month * 100 + newDay;
}

static long compressTimeBucket(long timeBucket,int dayStep){
    if (dayStep <= 0){ 
        throw new IllegalArgumentException("dayStep must be positive"); 
    }
    long year = timeBucket / 10000;
    long monthDay = timeBucket % 10000;
    long month = monthDay / 100;
    long day = monthDay % 100;
    int newDay = ((int)day - 1) / dayStep * dayStep + 1;
    return year * 10000 + month * 100 + newDay;
}

static long compressTimeBucket(long timeBucket,int dayStep){
    try{
        if(dayStep<=0) return timeBucket;
        long year = timeBucket/10000;
        long monthDay = timeBucket%10000;
        long month = monthDay/100;
        long day = monthDay%100;
        long compressedDay = day - ((day-1)%dayStep);
        if(compressedDay<1) compressedDay = 1;
        return year*10000 + month*100 + compressedDay;
    }catch(Exception e){
        return timeBucket;
    }
}

static long compressTimeBucket(long timeBucket,int dayStep){
    if (dayStep <= 0){
        return timeBucket;
    }
    String bucketStr = Long.toString(timeBucket);
    if (bucketStr.length() != 8){
        return timeBucket;
    }
    try{
        int year = Integer.parseInt(bucketStr.substring(0,4));
        int month = Integer.parseInt(bucketStr.substring(4,6));
        int day = Integer.parseInt(bucketStr.substring(6,8));
        int bucketDay = ((day - 1) / dayStep) * dayStep + 1;
        String resStr = String.format("%04d%02d%02d", year, month, bucketDay);
        return Long.parseLong(resStr);
    }catch (NumberFormatException e){
        return timeBucket;
    }
}

static long compressTimeBucket(long timeBucket, int dayStep){ 
    if(dayStep <= 0){ 
        throw new IllegalArgumentException("dayStep must be greater than 0"); 
    } 
    int day = (int)(timeBucket % 100); 
    if(day < 1 || day > 31){ 
        throw new IllegalArgumentException("invalid day in timeBucket: " + timeBucket); 
    } 
    long yearMonth = timeBucket - day; 
    int newDay = ((day - 1) / dayStep) * dayStep + 1; 
    return yearMonth + newDay; 
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if(str==null || len<=0) return 0;
    int maxLen=str.length();
    int start=Math.max(0,index);
    int end=Math.min(maxLen,start+len);
    if(start>=end) return 0;
    int utf8Size=0;
    for(int i=start;i<end;){
        int cp=str.codePointAt(i);
        if(cp<=0x7F){
            utf8Size+=1;
        }else if(cp<=0x7FF){
            utf8Size+=2;
        }else if(cp<=0xFFFF){
            utf8Size+=3;
        }else{
            utf8Size+=4;
        }
        i+=Character.charCount(cp);
    }
    return utf8Size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len){
    if (str == null) {
        throw new NullPointerException("String is null");
    }
    int end;
    try {
        end = index + len;
    } catch (ArithmeticException ex) {
        throw new IndexOutOfBoundsException("Index and length overflow");
    }
    if (index < 0 || len < 0 || end > str.length()) {
        throw new IndexOutOfBoundsException(
                "index (" + index + ") and len (" + len + ") out of bounds");
    }
    int size = 0;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        if (ch < 0x80) {
            size++;
        } else if (ch < 0x800) {
            size += 2;
        } else if (ch >= 0xD800 && ch <= 0xDBFF) { // possible high surrogate
            if (i + 1 < end) {
                char low = str.charAt(i + 1);
                if (low >= 0xDC00 && low <= 0xDFFF) {
                    // valid surrogate pair
                    size += 4;
                    i++; // skip low surrogate
                } else {
                    // invalid surrogate, treat high surrogate as 3 bytes
                    size += 3;
                }
            } else {
                // dangling high surrogate at end, treat as 3 bytes
                size += 3;
            }
        } else {
            size += 3;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if (str == null || len <= 0) {
        return 0;
    }
    int start = Math.max(index, 0);
    int end = Math.min(str.length(), start + len);
    int bytes = 0;
    for (int i = start; i < end; i++) {
        char ch = str.charAt(i);
        if (ch < 0x80) {
            bytes += 1;
        } else if (ch < 0x800) {
            bytes += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
                bytes += 4;
                i++; // skip the low surrogate
            } else {
                bytes += 3;
            }
        } else {
            bytes += 3;
        }
    }
    return bytes;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len){
    if (str == null) return 0;
    int size = 0;
    int max = index + len;
    if (max > str.length()) max = str.length();
    if (index < 0 || max <= index) return 0;
    for (int i = index; i < max; ) {
        char ch = str.charAt(i);
        if (Character.isHighSurrogate(ch) && i + 1 < max) {
            char low = str.charAt(i + 1);
            if (Character.isLowSurrogate(low)) {
                size += 4;
                i += 2;
                continue;
            }
        }
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else {
            size += 3;
        }
        i++;
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if (str == null || len <= 0){
        return 0;
    }
    int strLen = str.length();
    int start = index;
    if (start < 0) {
        start = 0;
    }
    if (start > strLen) {
        return 0;
    }
    int end = start + len;
    if (end > strLen) {
        end = strLen;
    }
    int size = 0;
    for (int i = start; i < end; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            // check if next char is low surrogate
            if (i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
                size += 4; // surrogate pair represents a code point > U+FFFF
                i++; // skip low surrogate
            } else {
                // unmatched high surrogate, treat as 3-byte sequence
                size += 3;
            }
        } else if (Character.isLowSurrogate(ch)) {
            // unmatched low surrogate, treat as 3-byte sequence
            size += 3;
        } else {
            size += 3;
        }
    }
    return size;
}

