public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        return lb;
    }
    byte[] utf8Bytes;
    try {
        utf8Bytes = str.toString().getBytes("UTF-8");
    } catch (Exception e) {
        throw new RuntimeException(e);
    }

    int offset = 0;
    LinkedBuffer buffer = lb;
    while (offset < utf8Bytes.length) {
        int toWrite = Math.min(buffer.remaining(), utf8Bytes.length - offset);
        System.arraycopy(utf8Bytes, offset, buffer.data, buffer.position, toWrite);
        buffer.position += toWrite;
        offset += toWrite;
        if (offset < utf8Bytes.length) {
            buffer = buffer.next();
        }
    }
    return buffer;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("String argument cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer argument cannot be null");
    }
    try {
        byte[] utf8Bytes = str.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);
        // Assume LinkedBuffer has a method to write raw bytes.
        if (lb instanceof java.nio.ByteBuffer) {
            ((java.nio.ByteBuffer) lb).put(utf8Bytes);
        } else {
            // Fallback: try a generic write method if available
            java.lang.reflect.Method writeMethod = null;
            try {
                writeMethod = lb.getClass().getMethod("write", byte[].class);
                writeMethod.invoke(lb, (Object) utf8Bytes);
            } catch (NoSuchMethodException e) {
                // If no such method, try write(byte[], int, int)
                try {
                    writeMethod = lb.getClass().getMethod("write", byte[].class, int.class, int.class);
                    writeMethod.invoke(lb, utf8Bytes, 0, utf8Bytes.length);
                } catch (Exception ex) {
                    throw new RuntimeException("Unable to write bytes to LinkedBuffer", ex);
                }
            }
        }
        return lb;
    } catch (Exception e) {
        throw new RuntimeException("Failed to write UTF-8 bytes to LinkedBuffer", e);
    }
}

