public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    // Remove leading '/' for absolute paths
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    // Split into segments
    String[] parts = path.split("/", -1); // keep trailing empty segments
    for (String part : parts) {
        if (part == null) {
            continue;
        }
        try {
            if (decode) {
                part = java.net.URLDecoder.decode(part, "UTF-8");
            }
        } catch (Exception e) {
            // If decoding fails, keep the original percent‑encoded segment
        }
        segments.add(new PathSegmentImpl(part));
    }
    return segments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    // Split by '/' but ignore leading '/'. The split will produce empty strings for leading/trailing slashes.
    String[] pieces = path.split("/");
    for (String piece : pieces) {
        if (piece.isEmpty()) {
            continue;
        }
        String decoded = piece;
        if (decode) {
            try {
                decoded = java.net.URLDecoder.decode(piece, "UTF-8");
            } catch (java.io.UnsupportedEncodingException e) {
                throw new RuntimeException(e);
            }
        }
        segments.add(new PathSegmentImpl(piece, decoded));
