    double minY = box.getMinY();
    double maxY = box.getMaxY();

    // Ensure coordinates are ordered correctly
    double leftMinX = Math.min(minX, maxX);
    double leftMaxX = Math.max(minX, maxX);

    double midX = (leftMinX + leftMaxX) / 2.0;

    Box2D leftBox = new Box2D(leftMinX, minY, midX, maxY);
    Box2D rightBox = new Box2D(midX, minY, leftMaxX, maxY);

    return Pair.of(leftBox, rightBox);
}

public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    if (box == null){
        throw new IllegalArgumentException("box cannot be null");
    }
    double width = box.getWidth();
    if (width <= 0){
        throw new IllegalArgumentException("box width must be positive");
    }
    double halfWidth = width / 2.0;
    double x = box.getX();
    double y = box.getY();
    double height = box.getHeight();
    Box2D left = new Box2D(x, y, halfWidth, height);
    Box2D right = new Box2D(x + halfWidth, y, halfWidth, height);
    return Pair.of(left, right);
}

