public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (node == null) {
        return 0;
    }
    int total = 0;
    while (node != null) {
        int start = node.readPos;
        int len = node.writePos - start;
        if (len > 0) {
            out.write(node.buffer, start, len);
            total += len;
        }
        node = node.next;
    }
    return total;
}

