            }
        }
        if (prime) {
            return candidate;
        }
        candidate += (candidate == 2 ? 1 : 2);
        if (candidate > bound && desiredCapacity >= 1000) {
            // If we exceed the 11% bound, continue searching without restriction.
            bound = Integer.MAX_VALUE;
        }
    }
}

