public static String trimTrailingWhitespace(String str){
    if (str == null) return null;
    int len = str.length();
    if (len == 0) return str;
    int idx = len - 1;
    while (idx >= 0 && Character.isWhitespace(str.charAt(idx))) {
        idx--;
    }
    if (idx == len - 1) {
        return str;
    }
    return str.substring(0, idx + 1);
}

