private JsonObject convertProperties(List<KeyStringValuePair> properties){
    JsonObject json = new JsonObject();
    if(properties == null) return json;
    for(KeyStringValuePair kv : properties){
        if(kv == null) continue;
        String key = kv.getKey();
        Object val = kv.getValue();
        if(key == null) continue;
        if(val == null){
            json.add(key, JsonNull.INSTANCE);
        }else if(val instanceof Number){
            json.addProperty(key, (Number) val);
        }else if(val instanceof Boolean){
            json.addProperty(key, (Boolean) val);
        }else if(val instanceof String){
            json.addProperty(key, (String) val);
        }else if(val instanceof Character){
            json.addProperty(key, (Character) val);
        }else{
            json.add(key, new JsonPrimitive(val.toString()));
        }
    }
    return json;
}

