public static long factorial(int n){
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }
    long result = 1L;
    for (int i = 1; i <= n; i++) {
        if (result > Long.MAX_VALUE / i) {
            throw new ArithmeticException("Long overflow while computing factorial");
        }
        result *= i;
    }
    return result;
}

