private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir){
    if (predicate == null) throw new IllegalArgumentException("predicate must not be null");
    if (start == null || stop == null) throw new IllegalArgumentException("start and stop nodes must not be null");
    // Initialise a circulator at the start node in the given direction
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    while (circ != null) {
        Node current = circ.getNode();
        if (predicate.test(current)) {
            return circ; // found a node satisfying the predicate
        }
        if (current.equals(stop)) {
            return circ; // reached the stop node
        }
        circ = circ.next(); // advance to the next node on the outer face
    }
    // If traversal somehow terminates without finding the stop node, return one at stop
    return new OuterFaceCirculator(stop, dir);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate cannot be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("Start node cannot be null");
    }
    if (stop == null) {
        // If no stop node is specified just start at the start node.
        return new OuterFaceCirculator(start, dir);
    }

    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    if (predicate.test(circ.getNode())) {
        return circ;
    }

    // Traverse around the outer face until we reach the stop node or find a matching node
    while (!circ.getNode().equals(stop)) {
        try {
            circ.next();
        } catch (RuntimeException e) {
            // If the circulator cannot advance (e.g., at a dead‑end), break to avoid infinite loop
            break;
        }
        if (circ.getNode() == null) {
            break;
        }
        if (predicate.test(circ.getNode())) {
            return circ;
        }
    }

    // Ensure we return a circulator that points at the stop node
    if (!circ.getNode().equals(stop)) {
        circ = new OuterFaceCirculator(stop, dir);
    }
    return circ;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
