    if (start == null || stop == null) {
        throw new IllegalArgumentException("Start and stop nodes must not be null");
    }

    OuterFaceCirculator current = new OuterFaceCirculator(start, dir);

    // If the starting node already satisfies the predicate, return immediately.
    if (predicate.test(current.get())) {
        return current;
