    // Traverse until we reach the stop node or find a node that satisfies the predicate.
    while (!current.get().equals(stop)) {
        try {
            current.move(dir);
        } catch (RuntimeException e) {
            // If the circulator cannot move further (e.g., reached boundary), return the current node.
            return current;
        }

        Node node = current.get();
        if (predicate.test(node)) {
            return current;
        }
    }

    // If we exit the loop, we are at the stop node; return it.
    return current;
