private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir){
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate must not be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("Start and stop nodes must not be null");
    }
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

    // Check the starting node first
    Node current = circ.get();
    if (predicate.apply(current) || current.equals(stop)) {
        return circ;
    }

    // Iterate around the outer face until the predicate is satisfied or the stop node is reached
    while (true) {
        circ.next();
        current = circ.get();
        if (predicate.apply(current)) {
            return circ;
        }
        if (current.equals(stop)) {
            return circ;
        }
    }
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new NullPointerException("predicate cannot be null");
    }
    if (start == null) {
        throw new NullPointerException("start node cannot be null");
    }
    if (stop == null) {
        throw new NullPointerException("stop node cannot be null");
    }

    // Create a circulator positioned at the starting node and pre‑set to the desired direction.
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

    // Current node reference for easy comparisons.
    Node current = circ.getNode();

    // Traverse until we either encounter the stop node or a node satisfying the predicate.
    while (!current.equals(stop) && !predicate.test(current)) {
        circ.move();   // Advance the circulator in the preset direction.
        current = circ.getNode();
    }

    return circ;
}

