    try {
        if (r == null) {
            return Action.CONTINUE;
        }
        // Automatically suspend long‑polling resources
        if (r.getTransport() == AtmosphereResource.TRANSPORT.LONG_POLLING) {
            try {
                r.suspend();
            } catch (Exception e) {
                // If suspend fails, just continue without interruption
            }
        }
    } catch (Throwable t) {
        // Generic catch to avoid any runtime failure in inspector
    }
    return Action.CONTINUE;
}

