    if (r == null) {
        return Action.CONTINUE;
    }
    try {
        if (r.getTransport() != AtmosphereResource.TRANSPORT.WEBSOCKET) {
            r.suspend();
        }
    } catch (Exception ignored) {
        // swallow exceptions; the callback must not interrupt processing
    }
    return Action.CONTINUE;
}

@Override public Action inspect(AtmosphereResource r){
    try {
        if (r.getTransport() != null) {
            switch (r.getTransport()) {
                case LONG_POLLING:
                case SSE:
                case SCRIPT:
                case FALLBACK:
                    r.suspend();
                    break;
                default:
                    // no suspend needed
                    break;
            }
        }
    } catch (Exception ignored) {
        // ignore any suspend failures
    }
    return Action.CONTINUE;
}

