    try {
        // Automatically suspend the resource depending on its transport type
        if (r.getTransport() == AtmosphereResource.TRANSPORT.HTTP ||
            r.getTransport() == AtmosphereResource.TRANSPORT.WEBSOCKET ||
            r.getTransport() == AtmosphereResource.TRANSPORT.XHR) {
            // Suspend only if not already suspended to avoid redundant calls
            try {
                if (!r.isSuspended()) {
                    r.suspend();
                }
            } catch (Throwable t) {
                // Ignore any errors during suspension
            }
        }
    } catch (Throwable ignored) {
        // Ignore failures to inspect transport or suspend
    }
    return Action.CONTINUE;
}

