        throw new IllegalArgumentException("elements must be non‑negative");
    }
    if (elements > pos) {
        throw new IllegalArgumentException(
            "cannot pop " + elements + " elements from stack with only " + pos + " elements");
    }
    for (int i = 0; i < elements; i++) {
        stack[--pos] = null;  // clear reference for GC
    }
}

private void pop(final int elements){
    if (elements < 0) {
        throw new IllegalArgumentException("Number of elements to pop must be non-negative");
    }
    int newPos = outputFrameStackPos - elements;
    if (newPos < 0) {
        throw new EmptyStackException();
    }
    for (int i = 0; i < elements; i++) {
        outputFrameStack[newPos + i] = null; // Allow GC to reclaim space
    }
    outputFrameStackPos = newPos;
}

private void pop(final int elements){
    if (elements < 0) {
        throw new IllegalArgumentException("elements must be non‑negative");
    }
    int remaining = elements;
    while (remaining > 0) {
        if (pos == 0) {
            throw new IllegalStateException("Stack underflow");
        }
        pos--;
        stack[pos] = null;
        remaining--;
    }
}

private void pop(final int elements) {
    if (elements < 0) {
        throw new IllegalArgumentException("elements must be non-negative: " + elements);
    }
    if (elements > pos) {
        throw new EmptyStackException();
    }
    while (elements-- > 0) {
        stack[--pos] = null;
    }
}

