private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null) {
        throw new IllegalArgumentException("bounds cannot be null");
    }
    int n = bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    long total = 0L;
    for (int i = 0; i < n; i++) {
        Integer val = bounds.get(i);
        if (val == null) {
            throw new IllegalArgumentException("bounds element at index " + i + " is null");
        }
        total += val;
    }
    long running = 0L;
    for (int i = n - 1; i >= 0; i--) {
        running += bounds.get(i);
        suffix.add(0, (int) running);
    }
    return new Pair<>(suffix, total);
}

