    try{
        if(bounds==null){
            return Pair.of(new ArrayList<Integer>(),0L);
        }
        int n=bounds.size();
        List<Integer> suffix=new ArrayList<>(n);
        long running=0;
        for(int i=n-1;i>=0;i--){
            Integer v=bounds.get(i);
            long val=v==null?0L:v.longValue();
            running+=val;
            suffix.add(0,(int)running);
        }
        long total=0;
        for(Integer v:bounds){
            if(v!=null){
                total+=v;
            }
        }
        return Pair.of(suffix,total);
    }catch(Exception e){
        return Pair.of(new ArrayList<Integer>(),0L);
    }
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null || bounds.isEmpty()){
        return new Pair<>(new ArrayList<>(), 0L);
    }
    int size = bounds.size();
    long[] suffixArr = new long[size];
    long running = 0L;
    for (int i = size - 1; i >= 0; i--) {
        running += bounds.get(i);
        suffixArr[i] = running;
    }
    List<Integer> suffixList = new ArrayList<>(size);
    for (long val : suffixArr) {
        suffixList.add((int) val);
    }
    long totalSum = 0L;
    for (int val : bounds) {
        totalSum += val;
    }
    return new Pair<>(suffixList, totalSum);
}

