public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array must not be null");
    }
    int length = arr.length;
    if (from < 0 || to >= length) {
        throw new IllegalArgumentException("Index out of bounds: from=" + from + ", to=" + to + ", length=" + length);
    }
    if (from > to) {
        // Nothing to reverse; return silently
        return;
    }
    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

public static final <V> void reverse(V[] arr,int from,int to){
    if(arr == null) throw new NullPointerException("Array is null");
    if(from < 0 || to >= arr.length) throw new IndexOutOfBoundsException("Index out of bounds");
    if(from > to) return;
    int i = from, j = to;
    while(i < j){
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++; j--;
    }
}

