public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        return;
    }
    int rowCount = table.getRowCount();
    if (row < 0 || row >= rowCount) {
        return;
    }
    try {
        // Select the specified row
        table.setRowSelectionInterval(row, row);
        // Ensure the row is visible in the scroll pane
        Rectangle rect = table.getCellRect(row, 0, true);
        table.scrollRectToVisible(rect);
        // Delay the repaint to allow the table to finish painting the new selection
        SwingUtilities.invokeLater(() -> table.repaint(rect));
    } catch (Exception e) {
        // Handle any unexpected exceptions gracefully
        // (logging could be added here if desired)
    }
}

