public void abbreviate(final int nameStart, final StringBuffer buf){
    if(buf == null || nameStart < 0 || nameStart > buf.length()){
        return;
    }
    // Extract the name substring starting at nameStart
    final String name = buf.substring(nameStart);
    if(name.isEmpty()){
        return;
    }
    final StringBuilder abbr = new StringBuilder();
    int i = 0;
    while(i < name.length()){
        // Skip any leading whitespace within the name part
        while(i < name.length() && Character.isWhitespace(name.charAt(i))){
            i++;
        }
        if(i >= name.length()){
            break;
        }
        // Append the first character of the word followed by '.'
        abbr.append(name.charAt(i)).append('.');
        // Advance to the end of the current word
        while(i < name.length() && !Character.isWhitespace(name.charAt(i))){
            i++;
        }
    }
    // Replace the original name in the buffer with its abbreviation
    buf.replace(nameStart, buf.length(), abbr.toString());
}

public void abbreviate(final int nameStart, final StringBuffer buf){
    if (buf == null){
        return;
    }
    // Assumes there is a String field named 'name' in the surrounding class
    if (name == null || name.isEmpty()){
        return;
    }
    int start = nameStart;
    if (start < 0 || start >= name.length()){
        return;
    }
    // Skip any leading spaces
    while (start < name.length() && name.charAt(start) == ' '){
        start++;
    }
    if (start >= name.length()){
        return;
    }
    buf.append(name.charAt(start));
    buf.append('.');
}

public void abbreviate(final int nameStart,final StringBuffer buf){
    if (buf == null) {
        throw new IllegalArgumentException("Buffer cannot be null");
    }
    if (nameStart < 0) {
        throw new IllegalArgumentException("nameStart cannot be negative");
    }
    // Assume a method getName() exists that returns the full name string
    String fullName = getName();
    if (fullName == null || fullName.isEmpty()) {
        return;
    }
    String[] words = fullName.trim().split("\\s+");
    StringBuilder abbr = new StringBuilder();
    for (String w : words) {
        if (!w.isEmpty()) {
            abbr.append(Character.toUpperCase(w.charAt(0))).append('.');
        }
    }
    if (nameStart > buf.length()) {
        buf.append(abbr.toString());
    } else {
        buf.insert(nameStart, abbr.toString());
    }
}

