private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }
    int index = 0;
    // If descriptor represents a method, skip the '(' and pop all argument types.
    if (descriptor.charAt(0) == '(') {
        index++; // skip '('
        while (index < descriptor.length() && descriptor.charAt(index) != ')') {
            // Skip array brackets (any number of them)
            while (index < descriptor.length() && descriptor.charAt(index) == '[') {
                index++;
            }
            // At this point, descriptor.charAt(index) is the type code
            char type = descriptor.charAt(index);
            int slots = (type == 'J' || type == 'D') ? 2 : 1;
            // Decrease the frame stack position by the number of slots
            pos -= slots;
            // If the type is an object, move index past the ';'
            if (type == 'L') {
                index = descriptor.indexOf(';', index) + 1;
            } else {
                index++; // primitive or long/double
            }
        }
    } else {
        // Descriptor is a field descriptor; pop just this type
        // Skip array brackets
        while (index < descriptor.length() && descriptor.charAt(index) == '[') {
            index++;
        }
        char type = descriptor.charAt(index);
        int slots = (type == 'J' || type == 'D') ? 2 : 1;
        pos -= slots;
        // We do not actually need to advance index further here because no following types
    }
    // Ensure pos does not become negative; if it does it indicates misuse
    if (pos < 0) {
        throw new IllegalStateException("Frame stack underflow when popping descriptor: " + descriptor);
    }
}

