public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("path and relativePath must not be null");
    }
    boolean leadingSlash = path.startsWith("/");
    // Split path and relativePath on '/' and ignore empty tokens (which can appear due to leading/trailing '/')
    String[] baseTokens = path.split("/");
    String[] relTokens = relativePath.split("/");
    java.util.ArrayDeque<String> stack = new java.util.ArrayDeque<>();
    for (String token : baseTokens) {
        if (!token.isEmpty()) {
            stack.addLast(token);
        }
    }
    for (String token : relTokens) {
        if (token.isEmpty() || token.equals(".")) {
            continue; // no effect
        } else if (token.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            }
        } else {
            stack.addLast(token);
        }
    }
    StringBuilder sb = new StringBuilder();
    if (leadingSlash) {
        sb.append("/");
    }
    while (!stack.isEmpty()) {
        sb.append(stack.removeFirst());
        if (!stack.isEmpty()) {
            sb.append("/");
        }
    }
    return sb.length() == 0 ? "." : sb.toString();
}

