public int readTag() throws IOException {
    // Read the first byte of the tag
    int b = read();
    if (b == -1) {
        // End of stream: return zero tag
        return 0;
    }

    // If high bit is not set, then this byte is already the full tag
    if ((b & 0x80) == 0) {
        return b;
    }

    // Decode the remaining bytes of the varint
    int result = b & 0x7F;
    int shift = 7;
    while (true) {
        int next = read();
        if (next == -1) {
            // Unexpected EOF while reading a varint tag
            throw new EOFException();
        }
        result |= (next & 0x7F) << shift;
        if ((next & 0x80) == 0) {
            // End of varint
            return result;
        }
        shift += 7;
        // A tag in protobuf should be at most 5 bytes; if it exceeds that,
        // just ignore further bytes to avoid overflow
        if (shift > 28) {
            // Consume remaining bytes of the varint without affecting the result
            while ((next & 0x80) != 0) {
                next = read();
                if (next == -1) {
                    throw new EOFException();
                }
            }
            return result;
        }
    }
}

