            }
            if (snapshot == null) {
                continue;
            }
            if (timeRanges == null || timeRanges.isEmpty()) {
                snapshots.add(snapshot);
                continue;
            }
            long ts = snapshot.getTimestamp();
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (range != null && range.contains(ts)) {
                    snapshots.add(snapshot);
                    break;
                }
            }
        }
    }
    return snapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || !file.exists() || !file.isFile()) {
        throw new IllegalArgumentException("File must be a valid existing file");
    }
    List<ThreadSnapshot> allSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // Expect each line to be "timestamp|data"
            int sepIndex = line.indexOf('|');
            if (sepIndex <= 0 || sepIndex == line.length() - 1) {
                continue; // skip malformed line
            }
            String tsPart = line.substring(0, sepIndex);
            String dataPart = line.substring(sepIndex + 1);
            try {
                long timestamp = Long.parseLong(tsPart.trim());
                ThreadSnapshot snapshot = new ThreadSnapshot(timestamp, dataPart.trim());
                allSnapshots.add(snapshot);
            } catch (NumberFormatException e) {
                // skip lines with invalid timestamp
            }
        }
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        return allSnapshots;
    }
    List<ThreadSnapshot> filtered = new ArrayList<>();
    for (ThreadSnapshot ts : allSnapshots) {
        long tsTime = ts.getTimestamp(); // assumes ThreadSnapshot has this method
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            if (range.contains(tsTime)) { // assumes contains method
                filtered.add(ts);
                break;
            }
        }
    }
    return filtered;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            try {
                // Assume each line can be parsed into a ThreadSnapshot.
                ThreadSnapshot snapshot = ThreadSnapshot.parse(line);
                if (snapshot == null) {
                    continue; // skip if parsing failed
                }
                long ts = snapshot.getTimestamp(); // timestamp of the snapshot
                boolean inRange = true;
                if (timeRanges != null && !timeRanges.isEmpty()) {
                    inRange = false;
                    for (ProfileAnalyzeTimeRange range : timeRanges) {
                        if (ts >= range.getStart() && ts <= range.getEnd()) {
                            inRange = true;
                            break;
                        }
                    }
                }
                if (inRange) {
                    snapshots.add(snapshot);
                }
            } catch (Exception e) {
                // If a line cannot be parsed, ignore it and continue.
                continue;
            }
        }
    }
    return snapshots;
}
